-- 审核演示用：批量生成文章测试数据（本脚本插入 40 篇 review-post-*；列表接口 total 另含欢迎文等时可能为 41）
-- 目标库：ayeezblog
-- 说明：
-- 1) 脚本会插入一个专用分类（id=9001）
-- 2) 会先删除 id 以 review-post- 开头的旧演示文章，再重新插入，便于重复执行
-- 3) 每篇文章都包含标题、正文、封面、描述、时间与卡片标记字段

USE ayeezblog;
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- 演示分类（可重复执行）
INSERT INTO blog_category (id, parent_id, name, slug, description, sort)
VALUES (9001, NULL, '审核演示分类', 'review-demo-category', '用于热重载考核演示的测试分类', 9001)
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    slug = VALUES(slug),
    description = VALUES(description),
    sort = VALUES(sort);

-- 清理旧演示数据（可重复执行）
DELETE FROM blog_post WHERE id LIKE 'review-post-%';

